import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    """Remove path traversal attempts but preserve extension"""
    name = secure_filename(filename)
    if not name:
        name = 'unnamed_document.txt'
    return name

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'service': 'doc-converter'})

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    output_format = request.form.get('format', 'pdf')
    page_range = request.form.get('pages', '')

    safe_name = sanitize_filename(file.filename)
    job_id = generate_job_id(safe_name)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    input_path = os.path.join(job_dir, safe_name)
    file.save(input_path)

    # Build LibreOffice conversion command
    cmd = f'libreoffice --headless --convert-to {output_format}'

    if page_range:
        # Allow users to specify page range for conversion
        cmd += f' --printer-opt "PageRange={page_range}"'

    cmd += f' --outdir {job_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=60,
            cwd=job_dir
        )

        if result.returncode != 0:
            stderr = result.stderr.decode('utf-8', errors='replace')
            app.logger.error(f"Conversion failed: {stderr}")
            return jsonify({'error': 'Conversion failed', 'details': stderr[:200]}), 500

        # Find the output file
        base_name = os.path.splitext(safe_name)[0]
        output_path = os.path.join(job_dir, f"{base_name}.{output_format}")

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(
            output_path,
            as_attachment=True,
            download_name=f"{base_name}.{output_format}"
        )

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        app.logger.error(f"Unexpected error: {str(e)}")
        return jsonify({'error': 'Internal error'}), 500
    finally:
        # Cleanup is handled by a cron job
        pass

@app.route('/api/batch', methods=['POST'])
def batch_convert():
    """Convert multiple files - accepts JSON with base64 encoded files"""
    data = request.get_json()
    if not data or 'files' not in data:
        return jsonify({'error': 'No files in request'}), 400

    # Limit batch size
    if len(data['files']) > 10:
        return jsonify({'error': 'Maximum 10 files per batch'}), 400

    return jsonify({'error': 'Batch endpoint temporarily disabled'}), 503


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
